package forth

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
)

// Forth evaluates a sequence of Forth source lines and returns the
// resulting value stack, or an error if evaluation fails.
func Forth(input []string) ([]int, error) {
	f := newForth()
	for _, line := range input {
		tokens := strings.Fields(line)
		if len(tokens) == 0 {
			continue
		}
		if tokens[0] == ":" {
			if err := f.define(tokens[1:]); err != nil {
				return nil, err
			}
			continue
		}
		for _, tok := range tokens {
			if err := f.execToken(tok); err != nil {
				return nil, err
			}
		}
	}
	return f.stack, nil
}

// op is a single compiled action applied to the evaluator.
type op func(f *forth) error

type forth struct {
	stack []int
	defs  map[string][]op
}

func newForth() *forth {
	f := &forth{
		stack: []int{},
		defs:  make(map[string][]op),
	}

	f.defs["+"] = binaryOp(func(a, b int) (int, error) { return a + b, nil })
	f.defs["-"] = binaryOp(func(a, b int) (int, error) { return a - b, nil })
	f.defs["*"] = binaryOp(func(a, b int) (int, error) { return a * b, nil })
	f.defs["/"] = binaryOp(func(a, b int) (int, error) {
		if b == 0 {
			return 0, errors.New("divide by zero")
		}
		return a / b, nil
	})

	f.defs["dup"] = func(f *forth) error {
		x, err := f.pop()
		if err != nil {
			return err
		}
		f.stack = append(f.stack, x, x)
		return nil
	}
	f.defs["drop"] = func(f *forth) error {
		_, err := f.pop()
		return err
	}
	f.defs["swap"] = func(f *forth) error {
		b, err := f.pop()
		if err != nil {
			return err
		}
		a, err := f.pop()
		if err != nil {
			return err
		}
		f.stack = append(f.stack, b, a)
		return nil
	}
	f.defs["over"] = func(f *forth) error {
		b, err := f.pop()
		if err != nil {
			return err
		}
		a, err := f.pop()
		if err != nil {
			return err
		}
		f.stack = append(f.stack, a, b, a)
		return nil
	}

	return f
}

// binaryOp builds an op that pops two values (b on top, then a)
// and pushes the result of fn(a, b).
func binaryOp(fn func(a, b int) (int, error)) op {
	return func(f *forth) error {
		b, err := f.pop()
		if err != nil {
			return err
		}
		a, err := f.pop()
		if err != nil {
			return err
		}
		v, err := fn(a, b)
		if err != nil {
			return err
		}
		f.stack = append(f.stack, v)
		return nil
	}
}

func (f *forth) pop() (int, error) {
	if len(f.stack) == 0 {
		return 0, errors.New("empty stack")
	}
	v := f.stack[len(f.stack)-1]
	f.stack = f.stack[:len(f.stack)-1]
	return v, nil
}

// define parses the tokens of a `: name body ;` definition.
func (f *forth) define(tokens []string) error {
	if len(tokens) < 2 {
		return errors.New("unterminated colon definition")
	}
	name := strings.ToLower(tokens[0])
	if isNumber(name) {
		return errors.New("illegal operation: redefining a number")
	}
	var body []string
	for _, tok := range tokens[1:] {
		if tok == ";" {
			break
		}
		body = append(body, tok)
	}
	if len(body) == len(tokens)-1 {
		return errors.New("unterminated colon definition")
	}
	ops, err := f.compile(body)
	if err != nil {
		return err
	}
	f.defs[name] = ops
	return nil
}

// compile resolves each token of a definition body against the
// dictionary as it currently stands, so that words capture the
// meaning they had at definition time.
func (f *forth) compile(tokens []string) ([]op, error) {
	var ops []op
	for _, tok := range tokens {
		if isNumber(tok) {
			n, err := strconv.Atoi(tok)
			if err != nil {
				return nil, err
			}
			ops = append(ops, pushOp(n))
			continue
		}
		key := strings.ToLower(tok)
		def, ok := f.defs[key]
		if !ok {
			return nil, fmt.Errorf("undefined operation: %s", tok)
		}
		ops = append(ops, callOp(def))
	}
	return ops, nil
}

func pushOp(n int) op {
	return func(f *forth) error {
		f.stack = append(f.stack, n)
		return nil
	}
}

func callOp(def []op) op {
	return func(f *forth) error {
		for _, o := range def {
			if err := o(f); err != nil {
				return err
			}
		}
		return nil
	}
}

func (f *forth) execToken(tok string) error {
	if isNumber(tok) {
		n, err := strconv.Atoi(tok)
		if err != nil {
			return err
		}
		f.stack = append(f.stack, n)
		return nil
	}
	def, ok := f.defs[strings.ToLower(tok)]
	if !ok {
		return fmt.Errorf("undefined operation: %s", tok)
	}
	return callOp(def)(f)
}

// isNumber reports whether s is an optional minus sign followed by
// one or more ASCII digits.
func isNumber(s string) bool {
	if s == "" || s == "-" {
		return false
	}
	for i, r := range s {
		if i == 0 && r == '-' {
			continue
		}
		if r < '0' || r > '9' {
			return false
		}
	}
	return true
}

